CREATE TABLE IF NOT EXISTS schema_migrations(id INTEGER PRIMARY KEY); INSERT OR IGNORE INTO schema_migrations VALUES(1);
 CREATE TABLE IF NOT EXISTS candidates(id TEXT PRIMARY KEY);
 CREATE TABLE IF NOT EXISTS snapshots(id TEXT PRIMARY KEY,candidate_id TEXT NOT NULL REFERENCES candidates(id),data TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY,candidate_id TEXT NOT NULL REFERENCES candidates(id),snapshot_id TEXT NOT NULL REFERENCES snapshots(id),idempotency_key TEXT NOT NULL,request_digest TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('CREATED','VALIDATING','RUNNING','COMPLETED','INTERRUPTED')),data TEXT NOT NULL,UNIQUE(candidate_id,idempotency_key));
 CREATE TABLE IF NOT EXISTS check_results(run_id TEXT NOT NULL REFERENCES runs(id),check_id TEXT NOT NULL,attempt INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(run_id,check_id,attempt));
 CREATE TABLE IF NOT EXISTS artifacts(run_id TEXT NOT NULL REFERENCES runs(id),path TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(run_id,path));
 CREATE TABLE IF NOT EXISTS assessments(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),data TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS criteria_revisions(id TEXT PRIMARY KEY,data TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS approval_requests(id TEXT PRIMARY KEY,data TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS decisions(proposal_id TEXT PRIMARY KEY REFERENCES approval_requests(id),data TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY,run_id TEXT,data TEXT NOT NULL);